#include <iostream>
#include <string>
#include <vector>
#include <sstream>
using namespace std;

int main() {
    vector<string> lines;
    string line;
    while (getline(cin, line)) {
        lines.push_back(line);
    }

    size_t index = 0;
    auto next = [&]() -> string {
        if (index < lines.size()) {
            return lines[index++];
        }
        throw out_of_range("ArrayIndexOutOfBoundsException: There is no more input");
    };

    auto nextInt = [&]() -> int {
        return stoi(next());
    };

    int N = nextInt();
    string s = next();

    int sf = 0;
    int fs = 0;
    for (int i = 0; i < N - 1; i++) {
        if (s[i] == 'F' && s[i + 1] == 'S') {
            fs++;
        }
        if (s[i] == 'S' && s[i + 1] == 'F') {
            sf++;
        }
    }

    if (sf > fs) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}
