using namespace std;

class InputReader {
public:
    vector<string> list;
    size_t index = 0;
    size_t max = 0;

    InputReader(const vector<string>& input) : list(input), max(input.size()) {}

    bool hasNext() const {
        return index < max;
    }

    string next() {
        if (!hasNext()) {
            throw runtime_error("ArrayIndexOutOfBoundsException: There is no more input");
        }
        return list[index++];
    }
};

template <typename T>
T makeClone(const T& obj) {
    return obj;
}

set<string> makeClone(const set<string>& obj) {
    return obj;
}

int nextInt(InputReader& reader) {
    return stoi(reader.next());
}

vector<string> nextStrArray(InputReader& reader) {
    string line = reader.next();
    vector<string> result;
    stringstream ss(line);
    string token;
    while (ss >> token) {
        result.push_back(token);
    }
    return result;
}

vector<int> nextIntArray(InputReader& reader) {
    string line = reader.next();
    vector<int> result;
    stringstream ss(line);
    int num;
    while (ss >> num) {
        result.push_back(num);
    }
    return result;
}

vector<char> nextCharArray(InputReader& reader) {
    string line = reader.next();
    vector<char> result;
    for (char c : line) {
        result.push_back(c);
    }
    return result;
}

void myout(const string& s) {
    cout << s << endl;
}

void Main() {
    vector<string> lines;
    string line;
    while (getline(cin, line)) {
        lines.push_back(line);
    }

    InputReader reader(lines);

    int N = nextInt(reader);
    string s = reader.next();
    int sf = 0;
    int fs = 0;

    for (int i = 0; i < N - 1; i++) {
        if (s[i] == 'F' && s[i + 1] == 'S') {
            fs++;
        }
        if (s[i] == 'S' && s[i + 1] == 'F') {
            sf++;
        }
    }

    if (sf > fs) {
        myout("YES");
    } else {
        myout("NO");
    }
}

int main() {
    Main();
    return 0;
}

